//
//  MP3Fixtures.swift
//  CogPluginsTests
//
//  Real LAME 4.0 encodes (1.2 s of 440 Hz sine at 44100 Hz), embedded as
//  base64 the way TagWriterTests embeds its PNG. The silent header-only
//  frames MP3ChapterTests builds carry no Xing/Info, so they cannot prove
//  gapless or seek accuracy; these do. cbrStereo, vbrStereo and cbrMono carry
//  the LAME tag's delay/padding; noXingStereo has none (minimp3-ex scans);
//  itunSMPB adds an iTunes gapless COMM frame over the same audio.
//

import Foundation

enum MP3Fixtures {
	static let cbrStereo = ""

	static let vbrStereo = ""

	static let cbrMono = ""

	static let noXingStereo = ""

	static let itunSMPB = ""

	static let itunSMPBAlt = ""

	/// The same audio, chapters written by ffmpeg (CHAP/CTOC), not TagLib.
	static let ffmpegChapters = ""

	static func write(_ base64: String, to url: URL) throws {
		let data = Data(base64Encoded: base64)!
		try data.write(to: url)
	}
}
